INSERT IGNORE INTO `institutes` (`id`, `short_name`, `full_name`) VALUES
(1, 'ОБЩЕЕ', 'Общеуниверситетское мероприятие'),
(2, 'ИИЦТ', 'Институт инженерии и цифровых технологий'),
(3, 'ИМА', 'Институт «Морская академия»'),
(4, 'ИУТП', 'Институт управления, транспорта и производительности');
INSERT IGNORE INTO `event_categories` (`id`, `name`) VALUES
(1, 'Конференция'), (2, 'Хакатон'), (3, 'Олимпиада'), (4, 'Патриотическая акция'),
(5, 'Спортивное соревнование'), (6, 'Кураторский час'), (7, 'Мастер-класс'),
(8, 'Встреча/Экскурсия'), (9, 'Фестиваль/Концерт'), (10, 'Конкурс/Выставка');
INSERT INTO `events` (`id`, `title`, `category_id`, `institute_id`, `date_start`, `date_end`, `location`, `organizer`, `description`) VALUES
(1, 'Патриотическая акция «Огненные картины»', 4, 1, '2026-06-21', '2026-06-21', 'Монумент славы', 'ИМА', 'Масштабная патриотическая акция, посвященная 85-й годовщине начала Великой Отечественной войны. Участники создали масштабную композицию из зажженных свечей. Курсанты ВУЗа выступили не только участниками, но и волонтерами: координировали гостей, раздавали свечи и информационные листовки.'),
(2, 'Просветительско-патриотическое мероприятие.', 8, 1, '2026-06-05', '2026-06-05', 'Новосибирский государственный краеведческий музей.', 'Новосибирский государственный краеведческий музей.', 'Патриотическая и образовательная встреча. Участники посетили тематическую экскурсию по экспозиции «История Новосибирской области», где узнали о главных этапах развития региона. Вторая часть мероприятия была посвящена общению с участниками СВО и курсантами факультета сил особого назначения, которые поделились боевым опытом, рассказали о службе и ответили на вопросы ребят.'),
(3, 'Большой торжественный концерт в честь 75-летия СГУВТ.', 9, 1, '2026-05-14', '2026-05-14', 'СГУВТ', 'Руководство и ветераны СГУВТ. творческие коллективы СГУВТ.', 'Юбилейное торжество, посвященное 75-летию со дня основания ведущего отраслевого вуза Сибири. Центральной частью вечера стала церемония награждения преподавателей и сотрудников университета: им вручили Почетные грамоты и Благодарственные письма от Губернатора, Минобразования Новосибирской области, Мэра города и главы Центрального округа. Официальная часть сопровождалась яркой концертной программой, наполненной творческими номерами и пропитанной духом флотского братства.'),
(4, 'Телемост-встреча с участниками специальной военной операции', 8, 1, '2026-05-28', '2026-05-28', 'Дом офицеров Новосибирского гарнизона.', 'Мероприятие организовано на базе Дома офицеров', 'Патриотическая встреча в формате открытого диалога. На прямую видеосвязь с молодежью вышли действующие военнослужащие, включая бойца войск беспилотных систем (БПС). Студентам рассказали о специфике работы с беспилотниками, требованиях к кандидатам и обучении специалистов. Бойцы ответили на вопросы ребят о службе и мерах социальной поддержки. В финале встречи для учащихся провели экскурсию по Музею боевой славы воинов-сибиряков.'),
(5, 'Мастер-класс и турнир по грепплингу', 5, 1, '2026-05-23', '2026-05-23', 'СГУВТ', 'Новосибирский филиал школы единоборств «ШТОРМ» совместно с Новосибирской транспортной прокуратурой', 'Спортивно-массовое мероприятие, направленное на популяризацию здорового образа жизни. Программа состояла из двух частей: сначала тренер Евгений Истомин провел для ребят мастер-класс, показав комплекс упражнений и эффективные приемы единоборств, после чего студенты проверили свои силы в турнире по грепплингу (виду спортивной борьбы).'),
(6, 'Торжественный концерт в честь 75-летию СГУВТ', 9, 1, '2026-05-15', '2026-05-15', 'СГУВТ', 'Руководство вуза во главе с и.о. ректора К.С. Мочалиным, а также творческие объединения университета', 'Масштабный праздничный концерт, посвящённый 75-летнего юбилея университета. Со сцены прозвучали официальные поздравления от руководства вуза и приглашенных гостей регионального и городского уровней. Творческую программу вечера подготовили студенческие коллективы СГУВТ (вокальная студия «Маяк», танцевальная студия «Бриз», литклуб «Графит») и бойцы РСО, представившие номера, посвященные флотским традициям, истории вуза и преемственности поколений.'),
(7, 'Городское шествие «Бессмертный полк»', 4, 1, '2026-05-09', '2026-05-09', 'Шествие по улице «Красный проспект»', 'Всероссийское общественное движение «Волонтеры Победы» (Новосибирское отделение)', 'Масштабная патриотическая акция, посвященная Дню Победы. Студенты и курсанты университета выступили в роли волонтеров-координаторов: они помогали организовывать движение огромных колонн жителей, координировали людей на маршруте, сопровождали участников шествия и следили за порядком, обеспечивая достойное и спокойное проведение памятного мероприятия.'),
(8, 'Соревнования по многоборью ГТО', 5, 1, '2026-05-11', '2026-05-11', 'Спортивная площадка и спортивный комплекс СГУВТ', 'Кафедра «Теории, культуры» (ТСБИФК) во главе с главным судьей старшим преподавателем А.С. Шишовым', 'Внутривузовские спортивные соревнования по программе всероссийского комплекса ГТО. Студенты и курсанты соревновались в личном и командном первенствах, выполняя различные нормативы на силу, выносливость и скорость. По итогам упорной борьбы победу в общекомандном зачете одержал ИИЦТ, а в личных зачетах абсолютно лучшие результаты показали Анастасия Ломакина и Данил Сухотерин. Это было прямое межфакультетское противостояние, в котором приняли участие сборные всех трех институтов университета. Места распределились следующим образом: ИИЦТ - 1 место, ИУТП - 2 место, ИМА - 3 место.'),
(9, 'Интеллектуальная игра «По страницам Великой Отечественной войны» для иностранных студентов', 10, 1, '2026-04-29', '2026-04-29', 'Новосибирский государственный университет экономики и управления (НГУЭУ)', 'Руководство и организаторы НГУЭУ', 'Интеллектуально-патриотическая викторина, организованная в преддверии Дня Победы для иностранных студентов новосибирских вузов. Мероприятие направлено на повышение исторической грамотности, изучение ключевых событий и героев ВОВ, а также на формирование патриотического сознания. Студенты ИУТП и ИИЦТ ответили на вопросы викторины, закрепили знания об общей истории и получили по итогам игры памятные сувениры, сертификаты и дипломы.'),
(10, 'V городская студенческая патриотическая акция «Майский вальс»', 4, 1, '2026-05-07', '2026-05-07', 'Театральный сквер', 'Новосибирский государственный технический университет (НГТУ НЭТИ) совместно с НОВАТОМ', 'Юбилейный пятый сезон масштабной городской танцевальной акции, приуроченной к празднованию Дня Победы. Студенческие пары из различных учебных заведений Новосибирска синхронно исполнили вальс под военные мелодии на главной площади перед оперным театром, чтобы выразить благодарность и почтить память ветеранов и участников Великой Отечественной войны.'),
(11, 'Гала-концерт военно-патриотического фестиваля «Солдат войны не выбирает»', 9, 1, '2026-04-30', '2026-04-30', 'Актовый зал СГУВТ', 'СГУВТ совместно с Новосибирским государственным университетом архитектуры, дизайна и искусств им. А.Д. Крячкова (НГУАДИ) при поддержке Женского движения «Единой России» в Новосибирской области', 'Масштабный гала-концерт, на котором участники представили вокальные, танцевальные и литературные номера, посвященные Великой Отечественной войне. Особое внимание в постановках было уделено подвигу женщин на войне, медсестер, тружеников тыла и фронтовиков. Лучших артистов наградили дипломами и благодарственными письмами, а завершилось событие всеобщим исполнением песни «День Победы»'),
(12, 'Соревнования по стритболу среди девушек и баскетболу среди юношей', 5, 1, '2026-04-23', '2026-04-27', 'Спортивный комплекс СГУВТ', 'Тренер сборной команды университета по баскетболу Виктор Пятницкий (главный судья соревнований)', 'Внутривузовские спортивные турниры, прошедшие в рамках ежегодной спартакиады. Девушки выявляли сильнейших в стритболе (уличном баскетболе 3х3), a юноши соревновались в классическом баскетболе. По результатам обоих турниров абсолютным триумфатором соревнований стал Институт управления, транспортных процессов и права (ИУТП), забравший оба золота.'),
(13, 'Всероссийский исторический Диктант «Диктант Победы»', 4, 1, '2026-04-25', '2026-04-25', 'СГУВТ', 'Организаторы Всероссийской акции «Диктант Победы». В СГУВТ координацию осуществляли сотрудники университета', 'Международная и всероссийская историко-патриотическая акция, направленная на проверку знаний о Великой Отечественной войне и повышение исторической грамотности. Участники из СГУВТ за 45 минут ответили на 25 тестовых вопросов, посвященных ключевым битвам, важным историческим вехам и выдающимся личностям военных лет'),
(14, 'Встреча в рамках проекта «Новосибирь СВОи» (Всероссийский проект служения «Твой герой»)', 8, 1, '2026-04-19', '2026-04-19', 'Актовый зал СГУВТ', 'Проектная команда «Новосибирь СВОи» при поддержке сотрудника поддержки молодёжных инициатив СГУВТ Татьяны Васильевны Колдеко', 'Патриотическое мероприятие в формате живого и открытого диалога с участником специальной военной операции. Модератор и студенты обсудили с гостем его личную историю, детские мечты, источники внутренней силы и мотивации. Военнослужащий рассказал о своей службе, значении солдатской дружбы, адаптации к мирной жизни и специфике войск БПЛА. Студенты активно задавали вопросы из зала, интересуясь доставкой гуманитарной помощи, первыми эмоциями в зоне боевых действий и бытом бойцов.'),
(15, 'донорская акция «Наш дар во имя жизни»', 4, 1, '2026-04-15', '2026-04-15', 'Актовый зал СГУВТ', 'Новосибирский клинический центр крови совместно с руководством СГУВТ', 'Социально значимая и патриотическая акция по добровольной сдаче крови для нужд регионального здравоохранения. В развернутом на базе университета мобильном пункте специалисты Центра крови провели забор биоматериала у студентов, курсантов и сотрудников СГУВТ В соответствии со всеми медицинскими стандартами. Участники, среди которых была и второкурсница Арина Афанасьева, отметили важность личного вклада в спасение жизней, а руководство вуза подчеркнуло высокую социальную ответственность и сознательность университетского сообщества.'),
(16, 'Цикл кураторских часов, посвящённых памяти жертв геноцида советского народа в годы Великой Отечественной войны', 6, 1, '2026-04-10', '2026-04-19', 'Аудитории Сибирского государственного университета водного транспорта', 'Кураторы академических групп СГУВТ', 'Серия информационно-просветительских занятий, направленных на сохранение исторической правды и памяти о трагедии мирного населения СССР. Студенты и курсанты изучили архивные документы, рассекреченные материалы и свидетельства очевидцев, раскрывающие факты преступлений нацистов и их пособников на оккупированных территориях (массовые уничтожения, принудительные работы и насилие). Кураторские часы помогли ребятам глубже осмыслить масштабы геноцида и важность защиты исторической памяти.'),
(17, 'Всероссийский конкурс чтецов «Морская душа»', 10, 1, '2026-04-01', '2026-04-01', 'Актовый зал СГУВТ', 'Оргкомитет всероссийского конкурса. На базе университета координацию осуществляли творческие и профильные подразделения вуза', 'Масштабный творческий конкурс, посвященный художественному чтению поэтических и прозаических произведений. Участники представили на сцене университета разножанровые номера - от суровых морских драм до легких юмористических произведений. Конкурс продемонстрировал современное и драйвовое прочтение классики, позволив молодым талантам проявить свои чувства, артистизм и любовь к литературе.'),
(18, 'Торжественное мероприятие и праздничный концерт, посвященные Дню защитника Отечества', 9, 1, '2026-02-21', '2026-02-21', 'Актовый зал СГУВТ', 'Руководство и творческие подразделения СГУВТ', 'Патриотическое мероприятие и гала-концерт в честь 23 февраля. Официальную часть открыли поздравления и.о. ректора К.С. Мочалина и заместителя председателя профильной комиссии Общественной палаты Г.П. Гуляева, отметивших важность преемственности поколений и флотской чести. Творческую программу наполнили вокальные и танцевальные номера, подготовленные студентами и курсантами. Особый акцент был сделан на чествовании офицеров и ветеранов СГУВТ, передающих свой опыт будущим специалистам водного транспорта.'),
(19, 'Встреча с Героем - участником специальной военной операции И.О. Родиным', 8, 1, '2026-02-17', '2026-02-17', 'Актовый зал СГУВТ', 'Проектная команда федерального проекта «Твой герой» совместно с администрацией СГУВТ', 'Патриотическое мероприятие, направленное на вовлечение ветеранов и участников СВО в воспитание молодежи и формирование гражданского долга. Встреча прошла в формате открытого диалога. Илья Олегович Родин поделился с ребятами своей личной историей участия в боевых действиях, рассказал о фронтовом быте, трудностях передовой и непреложной ценности воинского братства. Студенты и курсанты смогли напрямую задать гостю вопросы о службе, жизненных ориентирах и современных вызовах, стоящих перед страной.'),
(20, 'Фестиваль науки в СГУВТ', 9, 1, '2026-01-17', '2026-01-17', 'Аудитории и площадки Сибирского государственного университета водного транспорта', 'Научное сообщество и руководство СГУВТ. Церемонию награждения провел исполняющий обязанности проректора по научной работе Борис Владимирович Палагушкин', 'Инновационный и интерактивный научно-популярный фестиваль, показавший практическую и драйвовую сторону флотской науки. Программа включила в себя «Лигу молодых ученых», где аспиранты защищали свои проекты по развитию отрасли, прикладные мастер-классы с демонстрацией приборов и живые лекции от профессоров вуза. В финале мероприятия состоялась торжественная церемония, на которой Б. В. Палагушкин вручил благодарственные письма сотрудникам и учащимся за вклад в развитие российской науки'),
(21, 'ІІ этап межведомственной оперативно-профилактической операции «Чистое поколение 2025»', 6, 1, '2025-11-12', '2025-11-21', 'Аудитории Сибирского государственного университета водного транспорта', 'Кураторы учебных групп СГУВТ при поддержке Управления молодежной политики', 'Профилактическая антинаркотическая акция, направленная на формирование у молодежи устойчивого негативного отношения к употреблению запрещенных веществ. В рамках операции кураторы провели интерактивные занятия, где разъяснили студентам медицинские и социальные последствия употребления психоактивных веществ (ПАВ), a также подробно остановились на юридической ответственности и уголовных последствиях за хранение и распространение наркотиков. Участникам дали четкие алгоритмы действий в рисковых ситуациях и напомнили о важности бдительности'),
(22, 'Интеллектуальная битва тематическая «Своя игра», посвященная Дню инженера-механика', 10, 1, '2025-10-30', '2025-10-30', 'Кафедра «Техническая механика и подъемно-транспортные машины» (ТМ и ПТМ) СГУВТ', 'Организаторами выступили студентка 4 курса Лада Каика и магистр 1 курса Максим Каменский под руководством заведующей кафедрой Людмилы Владимировны Пахомовой и доцента Веры Александровны Шарутиной', 'Интеллектуально-развлекательная игра, приуроченная к профессиональному празднику инженеров-механиков. Встреча открылась поздравлениями от руководства кафедры и напутствием от В. А. Шарутиной, отметившей важность упорства в освоении профессии. В ходе игры команды соревновались в знании механики, логике и смекалке. Победителем турнира с большим отрывом стала команда «Фиксики»'),
(23, 'Чемпионат университета по волейболу среди юношей', 5, 1, '2025-10-08', '2025-10-30', 'Спортивный комплекс СГУВТ', 'Тренер сборных команд университета по волейболу Юрий Константинович Шишов (главный судья соревнований)', 'Внутривузовские спортивные соревнования среди мужских команд, прошедшие на высоком эмоциональном уровне. Турнир стал частью юбилейной 72-й спартакиады вуза. В результате интересной и упорной борьбы на волейбольной площадке победу праздновала сборная ИИЦТ, серебряные награды завоевали представители ИУТП, а замкнули тройку призеров курсанты ИМА'),
(24, 'Просветительская встреча «Неоязыческие корни украинского нацизма» (в рамках цикла лекций по профилактике экстремизма)', 8, 1, '2025-10-31', '2025-10-31', 'Аудитории Сибирского государственного университета водного транспорта', 'Миссионерский отдел Новосибирской епархии совместно с администрацией СГУВТ. Спикером встречи выступил митрофорный протоиерей Александр Новопашин', 'Профилактическая встреча-лекция, посвященная анализу деструктивных идеологий. Отец Александр провел подробный исторический экскурс, раскрыв суть неонацистской идеологии и её связь с неоязыческими и сатанинскими культами, используемыми в политических целях. Спикер подробно остановился на методах вербовки в религиозные секты и предостерег студентов от вовлечения в экстремистскую деятельность. Также в рамках встречи режиссер и сценарист Александр Новопашин презентовал ребятам трейлеры двух своих авторских документально-публицистических фильмов.'),
(25, 'Чемпионат университета по волейболу среди девушек', 5, 1, '2025-10-23', '2025-10-23', 'Спортивный комплекс СГУВТ', 'Тренер сборных команд университета по волейболу Юрий Константинович Шишов (главный судья соревнований)', 'Внутривузовские спортивные соревнования по волейболу среди женских команд, приуроченные к юбилею университета. Турнир прошел в атмосфере красивой и эмоциональной борьбы. По итогам сыгранных матчей золотые медали завоевали студентки ИИЦТ, серебро забрала команда ИУТП, а почетное третье место досталось представительницам ИМА');
INSERT INTO `events` (`id`, `title`, `category_id`, `institute_id`, `date_start`, `date_end`, `location`, `organizer`, `description`) VALUES
(26, 'XXI Всероссийский конкурс молодежи «Моя законотворческая инициатива» (очный этап)', 10, 2, '2026-05-19', '2026-06-19', 'Москва', 'Общероссийская общественная организация «Национальная система развития...»', 'Престижный всероссийский конкурс, направленный на привлечение молодежи к государственному управлению и законотворческой деятельности. Студентка СГУВТ представила доклад в секции «Оборона и безопасность», посвященный улучшению законов в сфере кибербезопасности на объектах критической информационной инфраструктуры. Работа была признана лучшей: студентку наградили знаком отличия «Депутатский резерв» и пригласили на работу в Госдуму, а её научный руководитель получила золотой знак отличия. Тезисы работы будут опубликованы в официальном сборнике конкурса.'),
(27, 'Летний фестиваль Университета биотехнологий «Сканируй, пилотируй, пробуй»', 9, 2, '2026-06-06', '2026-06-06', 'Университет биотехнологий (площадка «Точка кипения»)', 'Новосибирский государственный аграрный университет совместно с индустриальными партнерами', 'Профориентационный и научно-популярный фестиваль, посвященный профессиям будущего на стыке инженерии и биотехнологий. Мероприятие открылось приветственным словом ректора Е.В. Рудого и выступлениями представителей производственных компаний. После официальной части студенты ИИЦТ приняли участие в соревновательных интерактивных локациях: «Гонке дронов», «Микробиологическом квизе» и «Соревновании по 3D-сканированию». В финале фестиваля прошла дегустация экзотических коктейлей и церемония награждения, на которой студенты нашего института получили памятные призы за высокие результаты в конкурсах.'),
(28, 'Карьерная встреча с представителем ООО «Тобольский ССРЗ»', 8, 2, '2026-06-16', '2026-06-16', 'Аудитории СГУВТ', 'Кураторы и наставники учебных групп... Спикер Алексей Владимирович Жуков', 'Профориентационная встреча с представителем градообразующего судостроительно-судоремонтного завода. Алексей Владимирович Жуков познакомил студентов со структурой предприятия, модернизацией его цехов, улучшением условий труда и ростом заработной платы. Особый интерес вызвал рассказ о завершении корпусо-сборочных работ на строящемся судне класса «река-море» (проект 72SDC14017) грузоподъемностью 9300 тонн. В завершение встречи представитель завода подробно рассказал о возможностях прохождения производственной практики и пригласил молодых специалистов ИИЦТ трудоустроиться на предприятие после окончания учебы.'),
(29, 'Экскурсия и встреча с бойцами СВО представителями войск беспилотных систем.', 8, 2, '2026-06-05', '2026-06-05', 'Новосибирский государственный краеведческий музей', 'Администрация Новосибирского государственного краеведческого музея совместно с представителями войск БПЛА', 'Патриотическое и просветительское мероприятие, совместившее изучение истории и общение с современными защитниками Отечества. В первой части встречи студенты ознакомились с постоянной экспозицией «История Новосибирской области», изучив уникальные предметы быта, элементы одежды переселенцев, а также архивные документы и боевые награды времен Великой Отечественной войны. Во второй части состоялась живая беседа с участниками СВО. Бойцы поделились личным фронтовым опытом, подробно рассказали о специфике службы в войсках БПЛА, процессе обучения управлению дронами, получении новых технических компетенций и отметили, что армейская служба дает мощный стимул для личностного роста.'),
(30, 'Подача заявок и участие в грантовых конкурсах «Студенческий стартап» и «Создай наше»', 10, 2, '2025-09-01', '2026-06-30', 'Дистанционные отборочные этапы', 'Фонд содействия инновациям и АСИ. Научное наставничество: К.В. Катковская', 'Научно-практическая и грантовая деятельность студентов-программистов ИИЦТ. В рамках конкурсов ребята представили две перспективные технологические разработки: Проект «Трекер здоровья» — индивидуальная разработка Михаила Алтуняна. Проект «Система симуляции радиообмена на судне» — совместный проект Алексея Захарова и Ильи Сидорчука. Обе инновационные ИТ-разработки успешно преодолели три серьезных отборочных этапа. Впереди у команд финальные испытания, по итогам которых решится вопрос о выделении целевого финансирования (грантов) на коммерциализацию и запуск их стартапов.'),
(31, 'VIII Всероссийская олимпиада по комплексу графических дисциплин (номинация «CAD-спринтер»)', 3, 2, '2026-05-19', '2026-05-19', 'База СГУПС', 'СГУПС при поддержке профильных вузов. Наставник СГУВТ: Ольга Валерьевна Щербакова', 'Масштабное всероссийское интеллектуальное соревнование в области инженерной графики и автоматизированного проектирования. Студенты ИИЦТ состязались в номинации «CAD-спринтер», где главным критерием были скорость и инженерная точность при трехмерном моделировании: участникам требовалось оперативно выполнить 5 сложных практических заданий. По результатам напряженной борьбы Константин Оникиенко завоевал абсолютное 1 место, а Егор Мешаев вошел в десятку сильнейших, заняв 7 место. Высоких результатов удалось достичь благодаря усердной подготовке студентов в рамках университетского кружка 3D-моделирования и прототипирования.'),
(32, 'Профориентационная встреча «Актуальная профессия инженер» с представителем компании «Инфинивейв»', 8, 2, '2026-05-12', '2026-05-12', 'Аудитории СГУВТ', 'Заведующий кафедрой ТКСТМ О.Ю. Лебедев и доцент М.Г. Мензилова. Спикер Александр Сергеевич Брагин', 'Карьерная встреча студентов-инженеров ИИЦТ с представителем технологического стартапа «Инфинивейв» (участник акселератора Технопарка Академгородка «А: СТАРТ», работающий совместно с Институтом гидродинамики им. М.А. Лаврентьева СО РАН). Спикер подробно рассказал о проектировании инженерных комплексов волновых бассейнов, гидродинамическом моделировании волн и специфике создания генераторов волнового прибоя. Студентов пригласили на постоянную работу и практику, где они смогут решать реальные задачи: от расчетов чаш бассейнов до монтажа сложных инженерных сетей. Прямой результат встречи: По итогам мероприятия студент группы К-231 Павел Рязановский успешно прошел отбор и получил в компании «Инфинивейв» должность инженера-экспериментатора, приступив к практической работе с волновым генератором.'),
(33, 'Патриотическое мероприятие «День Победы. Память о народных героях»', 4, 2, '2026-05-08', '2026-05-08', 'Аудитории СГУВТ', 'Заведующий кафедрой ТКСТМ О.Ю. Лебедев и доцент М.Г. Мензилова', 'Торжественный кураторский час, направленный на сохранение исторической памяти о подвиге советского народа. Организаторы обсудили со студентами масштабы самопожертвования солдат и тружеников тыла, важность защиты исторической правды и массовый героизм в ключевых сражениях ВОВ. Особое место в программе занял рассказ о выдающемся земляке, ветеране ВОВ и участнике Сталинградской битвы Александре Ивановиче Медведеве (1920-2025). Доцент М.Г. Мензилова поделилась со студентами воспоминаниями о личной встрече с ветераном и передала его главное напутствие будущим инженерам: «Берегите Россию!»'),
(34, 'Открытый конкурс научно-исследовательских работ среди студентов «Светотехника: дизайн и проектирование»', 10, 2, '2026-06-01', '2026-06-01', 'Аудитория 003 главного корпуса университета', 'Профильная кафедра института ИИЦТ. Авторы отчета Л.В. Садовская и Т.В. Ананьина', 'Внутривузовский конкурс научно-исследовательских и проектных работ, направленный на закрепление теоретических знаний и развитие навыков командного проектирования. Студенты разрабатывали инновационные инженерные решения для светового оснащения конкретной учебной аудитории (№ 003). Все участники продемонстрировали высокий уровень технической подготовки и погружение в актуальные задачи современной светотехники. По итогам защиты проектов места распределились следующим образом: 1-е место: Тимофей Рихтер, Кирилл Дячин, Денис Щекотов, Виолетта Половина. 2-е место: Ангелина Буданова, Данил Стариков, Лина Монгуш, Андрей Безрядин. 3-е место: Роман Гузенко, Кирилл Смирнов, Фёдор Бронников, Антон Зорин. Дипломы участников: Никита Рупец, Никита Казанцев, Юрий Павлов, Илья Коробейников.'),
(35, 'Конкурс «Инженер будущего 2026»', 10, 2, '2026-04-08', '2026-04-08', 'Дистанционный/очный формат', 'Фонд имени Б.Е. Бутомы и АО «Судостроительная корпорация «Ак Барс»', 'Престижный всероссийский конкурс для студентов инженерно-технических специальностей, направленный на вовлечение талантливой молодежи в решение сложных производственных задач судостроительной отрасли, Гособоронзаказа и Федеральных целевых программ. Экспертная комиссия оценивала инновационность технологий и передовые конструкторские решения участников. По итогам конкурса студент СГУВТ Пётр Сова продемонстрировал высочайший уровень подготовки и стал абсолютным победителем в номинации «Машиностроение (обработка материалов, мостостроение, сварочное производство)». Этот успех подтвердил высокую конкурентоспособность и отличные исследовательские компетенции будущих корабелов, формируемые на базе кафедры ТКСИТМ.'),
(36, 'Практический эксперимент по проверке грузоподъемности швертбота «Оптимист»', 7, 2, '2026-04-21', '2026-04-21', 'Лабораторная база СГУВТ', 'Сотрудники кафедры ТКСТМ и студенты СКБ', 'Научно-исследовательское и демонстрационное мероприятие в рамках работы СКБ. Участники провели стресс-тестирование корпуса швертбота «Оптимист», который штатно рассчитан только на детей до 12 лет (весом до 60 кг). Проверка показала, что судно успешно выдерживает экстремальную нагрузку в 280 кг, полностью сохраняя свои ключевые навигационные качества — плавучесть и остойчивость. В ходе эксперимента студенты и лицеисты на практике разобрали геометрию обводов корпуса, которая может послужить прототипом для проектирования малых шлюпок типа Динги.'),
(37, 'Всероссийская ярмарка трудоустройства', 10, 2, '2026-04-17', '2026-04-17', 'Новосибирский молодежный театр «Глобус»', 'Министерство труда и соцразвития НСО. Делегацию СГУВТ организовали С.В. Горелов, Д.Ю. Сахнов и Ю.Н. Смыков', 'Масштабное карьерное мероприятие, направленное на содействие в трудоустройстве студентов и выпускников. Будущие энергетики ИИЦТ изучили актуальные презентационные материалы ведущих работодателей региона, ознакомились с открытыми вакансиями и напрямую пообщались с представителями профильных компаний о востребованности специалистов их направления. Также студенты приняли участие в интерактивных викторинах и квизах. Особое внимание делегация СГУВТ уделила предложениям от предприятий электротехнического профиля, что позволило ребятам оценить реальные перспективы трудоустройства и требования рынка труда к молодым инженерам.'),
(38, 'Серия кураторских часов «День памяти жертв геноцида советского народа нацистами и их пособниками»', 6, 2, '2026-04-09', '2026-04-17', 'Аудитории СГУВТ', 'Кураторы и наставники ТКСТМ', 'Серия масштабных историко-патриотических встреч со студентами, направленная на сохранение исторической памяти, противодействие фальсификации фактов о Великой Отечественной войне и формирование негативного отношения к нацизму. Организаторы подробно разобрали со студентами трагическую статистику (26,6 млн общих потерь СССР, из которых 13,7 млн — гражданское население) и методы осуществления геноцида на оккупированных территориях (массовые расстрелы, блокада, Хатынь, концлагеря). Особое внимание уделили правовым вехам: Указу Президиума Верховного Совета СССР №39 от 19.04.1943 и Харьковскому судебному процессу 1943 года, где впервые был закреплен принцип ответственности за исполнение преступных приказов.'),
(39, 'Отборочный этап студенческой лиги Международного инженерного чемпионата «CASE-IN» (сезон 2025/2026)', 2, 2, '2026-06-01', '2026-06-01', 'База НГТУ', 'АНО «Россия - страна возможностей». Куратор от СГУВТ Ю.Н. Смыков', 'Масштабные инженерные соревнования, входящие в Общероссийский план молодежных мероприятий для популяризации ТЭК и инженерно-технического образования. Студенты решали сложный практический кейс, основанный на реальной производственной ситуации из сферы топливно-энергетического комплекса. По результатам защиты технологических решений команда «СГУВТ 1» обошла соперников, вышла в лидеры и одержала уверенную победу в отборочном этапе. Участники отметили высокий уровень организации и подтвердили намерение представлять институт на чемпионате в будущем.'),
(40, 'Практический эксперимент по проверке швертбота «Оптимист» на непотопляемость', 7, 2, '2026-04-14', '2026-04-14', 'Лабораторная база СГУВТ', 'Руководители СКБ - сотрудники кафедры ТКСТМ: О.Ю. Лебедев, М.Г. Мензилова, Д.Ю. Рыбников', 'Важный научно-исследовательский эксперимент, выполненный в рамках работы СКБ по официальному заказу Детского морского центра «Каравелла» им. А. Москаленко. Так как данный швертбот является головным (первым) проектом в строящейся серии судов, ему потребовалась обязательная проверка ключевых навигационных качеств. Поскольку судно предназначено для детей до 12 лет, обеспечение безопасности и непотопляемости было главным приоритетом. В ходе натурных испытаний исследователи и студенты смоделировали критические условия на воде, проверили плавучесть судна при заливании и успешно выявили конструктивные недостатки, которые в виде рекомендаций были направлены заказчику для последующего устранения.'),
(41, 'Кураторский час и час наставника «Урок патриотизма»', 6, 2, '2026-04-02', '2026-04-09', 'Аудитории СГУВТ', 'Кураторы и наставники кафедры ТКС и ТМ', 'Комплексное патриотическое и информационно-просветительское мероприятие, направленное на профилактику экстремизма, предупреждение вовлечения молодежи в преступную деятельность и повышение правовой грамотности. Программа кураторского часа включала два ключевых блока: Кинопоказ: Студенты просмотрели новый документальный фильм-расследование Андрея Медведева «Предательство» (2026 г.). На примере монологов осужденных ребят наглядно увидели скрытые механизмы вербовки молодежи через соцсети со стороны иностранных спецслужб и осознали тяжесть последствий. Изучение архивных материалов: Организаторы представили студентам официальную фотодокументальную подборку ЦОС ФСБ России. Будущие инженеры ИИЦТ ознакомились с публикациями СМИ о реальной работе ведомства по защите интересов страны.'),
(42, 'Кураторская экскурсия «Красота спасет мир»', 8, 2, '2026-04-02', '2026-04-02', 'Музей Н.К. Рериха', 'Экскурсионная служба музея. Куратор Л.В. Пахомова', 'Культурно-просветительская и эстетическая экскурсия для студентов ИИЦТ, направленная на расширение кругозора и духовно-нравственное развитие. Студенты погрузились в творчество выдающегося русского художника, мыслителя, ученого-археолога и путешественника Николая Константиновича Рериха. Вместе с экскурсоводом ребята подробно разобрали историю создания художественных полотен, отражающих древнее прошлое России, а также духовную связь автора с Азией и Западной Сибирью. Участники ознакомились с экспозицией, посвященной всей династии Рерихов, изучив подлинные мемориальные предметы быта семьи художника.'),
(43, 'Живая встреча студентов с участниками и ветеранами специальной военной операции', 8, 2, '2026-03-26', '2026-03-26', 'Актовый зал СГУВТ', 'Модератор профессор В.Ю. Гросс', 'Патриотическое и просветительское мероприятие в формате открытого диалога. В качестве почетных гостей перед студентами выступили: В.А. Шуев (подполковник ФСБ, ветеран СВО), С.В. Цикаленко (ветеран СВО), М.А. Амоскин (участник СВО), А.А. Фролов (участник СВО, курсант ИМА). Приглашенные гости искренне поделились своим фронтовым опытом, честно рассказали об особенностях быта на передовой, боевом братстве, силе духа и подчеркнули колоссальную важность писем поддержки, которые приходят от гражданских лиц и студентов. Встреча помогла ребятам глубже понять современные реалии и осознать значимость гражданской сплоченности.'),
(44, 'Профилактическая встреча «Будем бдительны!» с сотрудниками ФСБ и антитеррористического комитета', 8, 2, '2026-03-04', '2026-03-04', 'Актовый зал СГУВТ', 'Сотрудники Управления ФСБ России. При содействии руководства ИИЦТ', 'Комплексная рабочая встреча, направленная на обеспечение безопасности образовательной среды и противодействие экстремистским угрозам в молодежной среде. Представители ведомств детально ознакомили профессорско-преподавательский состав и студенческий актив с актуальными алгоритмами действий при возникновении чрезвычайных ситуаций или угроз терактов. Особое внимание спикеры уделили методам работы «вербовщиков» в социальных сетях и психологическим механизмам втягивания студентов в противоправную деятельность. Присутствующим напомнили базовые правила цифровой гигиены и личной безопасности.'),
(45, 'Просветительская беседа «Деструктивные образования как угроза личности, семье, обществу и государству»', 8, 2, '2026-03-17', '2026-03-17', 'Аудитории СГУВТ', 'Митрофорный протоиерей Александр Новопашин. Организована Д.Ю. Рыбниковым', 'Масштабная просветительская встреча, направленная на предупреждение вовлечения студенческой молодежи в опасные организации. Спикер подробно раскрыл классификацию деструктивных образований: от коммерческих лже-коучей и шарлатанов до опасных интернет-субкультур, суицидальных игр, религиозных сект и экстремистских структур. Отец Александр наглядно объяснил современные методы вербовки через социальные сети, онлайн-игры и технологии дипфейков, а также детально описал разрушительные последствия подобных манипуляций. В завершение беседы лектор дал студентам ИИЦТ практические рекомендации по защите своего сознания.'),
(46, 'Интеллектуальный квиз «В ПОИСКАХ ЭЛЕКТРОЭНЕРГИИ»', 10, 2, '2026-02-17', '2026-02-17', 'Аудитории СГУВТ', 'Старший преподаватель А.А. Каравка и жюри', 'Масштабная научно-познавательная игра в формате квиза, посвященная физическим и инженерным аспектам электроэнергетики. За победу развернулась упорная борьба между представителями разных институтов и приглашенными гостями. По итогам всех раундов 1-е место (46 баллов) заняла команда ИИЦТ «Дифференциалы» (Дарья Гусейнова, Алима Атамурзаева, Диана Исмаилова, Михаил Залыгин, Антон Жерновников, Елена Николаевна Кадышева). 2-е место: команда ИИЦТ «Т.Е.М.П.О.». 3-е место: команда ИУТП «Водники».'),
(47, 'Серия патриотических и военно-технических встреч (с участником СВО и инструкторами БПЛА)', 8, 2, '2026-02-17', '2026-02-19', 'Актовый зал СГУВТ', 'Участник СВО Илья Олегович и действующие инструкторы БПЛА', 'Цикл просветительских встреч, направленных на военно-патриотическое воспитание и ознакомление молодежи с современными оборонными технологиями. Мероприятия прошли в два этапа: 17 февраля: Состоялась встреча с бойцом СВО Ильей Олеговичем. Он детально рассказал о суровых реалиях боевых действий, сделав особый акцент на важности качественной экипировки. 19 февраля: Инструкторы БПЛА провели презентацию профильных курсов по подготовке операторов дронов. Гости продемонстрировали студентам ИИЦТ актуальные образцы беспилотных летательных аппаратов и поделились личным боевым опытом управления БПЛА.'),
(48, 'Кураторский час «Урок мужества», посвященный Дню защитника Отечества и годовщине вывода войск из Афганистана', 6, 2, '2026-02-17', '2026-02-17', 'Аудитории СГУВТ', 'Кураторы ТКСТМ', 'Торжественное военно-патриотическое мероприятие, приуроченное к 23 февраля и знаковой дате 15 февраля - Дню памяти о россиянах, исполнявших служебный долг за пределами Отечества. Перед студентами кораблестроительных специальностей выступил почетный гость — воин-интернационалист, ветеран боевых действий в Афганистане, член Российского Союза ветеранов Афганистана и СВО Виктор Владимирович Черневский. Заслуженный ветеран подробно рассказал молодежи об исторических предпосылках и задачах советского контингента в Афганистане, а также о примерах героизма и стойкости сослуживцев.'),
(49, 'Кураторская встреча: просмотр и обсуждение фильма «Зазеркалье» в рамках акции «Чистое поколение»', 6, 2, '2026-04-08', '2026-04-08', 'Аудитории СГУВТ', 'Кураторы учебных групп К.В. Катковская и Н.А. Рыковский', 'Профилактическое и воспитательное мероприятие, организованное в рамках масштабной общероссийской акции «Чистое поколение». Ключевым элементом встречи стал совместный кинопоказ художественного фильма «Зазеркалье». После просмотра кураторы провели со студентами открытое обсуждение картины, детально разобрав наиболее острые и актуальные для молодежи темы: специфику подростковой среды, сложные внутренние переживания и критическую важность осознания ответственности за принимаемые жизненные решения.'),
(50, 'Ежегодная 72-я студенческая научная конференция СГУВТ (заседание секций на кафедре Информационных систем)', 1, 2, '2026-04-16', '2026-04-16', 'Аудитории СГУВТ', 'Профессорско-преподавательский состав кафедры ИС', 'Традиционное научно-исследовательское мероприятие, объединившее молодых разработчиков и исследователей в сфере информационных технологий. Работа конференции была организована в рамках двух профильных секций, где студенты представили доклады о своих ИТ-изысканиях, продемонстрировали программные решения и обсудили актуальные тренды индустрии. По результатам экспертной оценки призовые места распределились следующим образом. Секция «Бакалавриат»: 1-е место: Дмитрий Лангер (гр. ИТ-221). 2-е место: Алексей Захаров и Максим Галкин (гр. ИТ-222). 3-е место: Анна Башарина, Андрей Кучер и Кирилл Мальцев (гр. ИТ-221). Секция «Магистратура»: 1-е место: Александр Моторин (гр. ИТМ-241).'),
(51, 'Кураторский кинопоказ и развернутое обсуждение документального фильма «Предательство»', 6, 2, '2026-04-04', '2026-04-08', 'Аудитории СГУВТ', 'Кураторы учебных групп К.В. Катковская и Н.А. Рыковский', 'Просветительское и гражданско-патриотическое мероприятие, направленное на профилактику экстремистских проявлений в молодежной среде и развитие критического мышления. Студенты старших курсов ИИЦТ посмотрели документальный фильм-расследование «Предательство» (2026 г.), раскрывающий механизмы вербовки российской молодежи иностранными спецслужбами для совершения диверсий. Ключевой частью встречи стал интерактивный развернутый диалог: будущие ИТ-специалисты активно включились в дискуссию, детально проанализировали скрытые опасности манипуляций в социальных сетях и рассмотрели последствия необдуманных решений.'),
(52, 'Праздничный визит в «Школу 21» в День российского студенчества', 8, 2, '2026-01-25', '2026-01-25', 'Новосибирский кампус «Школы 21»', 'Команда организаторов «Школы 21» при поддержке кураторов ИИЦТ', 'Нестандартное праздничное и профориентационное мероприятие, позволившее будущим ИТ-специалистам СГУВТ погрузиться в атмосферу реальной коммерческой разработки. Программа Дня открытых дверей состояла из трех интерактивных блоков: Практический воркшоп «Код, дизайн, данные: найди свою ИТ-стихию». Тематический квиз «Халява приди, или от сессии до сессии живут студенты весело». Технологическая экскурсия по кампусу, где ребята детально изучили экосистему школы, работающую в режиме 24/7, и познакомились с уникальной образовательной методикой «равный равному» (peer-to-peer) без лекций и классических преподавателей.'),
(53, 'Профориентационная встреча «Профессия инструктор БПЛА» (включая практические полеты на симуляторах и FPV-дронах)', 8, 2, '2026-01-20', '2026-01-20', 'Профильные лаборатории ИИЦТ СГУВТ', 'Министерство образования НСО и Дина Сергеевна Кузьминкова совместно с инструкторами', 'Масштабное практико-ориентированное мероприятие, посвященное одному из самых перспективных технологических направлений. Представители Министерства образования региона и практикующие эксперты подробно разобрали со студентами технические характеристики современных беспилотных систем, сферы их гражданского и специального применения, а также растущую востребованность квалифицированных наставников в этой области. В рамках практического блока каждый студент смог лично протестировать свои навыки пилотирования как на специализированных компьютерных симуляторах, так и в рамках реальных запусков высокоскоростных FPV-дронов.'),
(54, 'Посещение Дня ИТ-карьеры «Cookie Fest» и участие в хакатоне от маркетплейса Wildberries', 8, 2, '2025-12-10', '2025-12-10', 'Крупная региональная ИТ-площадка', 'Организаторы карьерного фестиваля Cookie Fest совместно с ИТ-департаментом компании Wildberries.', 'Масштабный практический выезд студентов старших курсов ИИЦТ на главный ИТ-карьерный фестиваль региона. Программа дня включала посещение лекций от топ-менеджеров индустрии, мастер-классы и прямой нетворкинг с потенциальными работодателями. Центральной точкой мероприятия стало участие сборной команды ИИЦТ в престижном хакатоне от маркетплейса Wildberries. Студенты решали реальный бизнес-кейс для сферы e-commerce — проектировали инновационные алгоритмы на базе нейросетей и машинного обучения для автоматической оптимизации карточек товаров. Разработчики СГУВТ успешно защитили свои ИИ-решения перед экспертной комиссией и получили ценный опыт.'),
(55, 'Научно-практическая конференция «Профессиональные компетенции в сфере ИТ технологий»', 1, 2, '2025-12-06', '2025-12-06', 'Аудитории СГУВТ', 'ППС кафедры ИС. Председатель комиссии - А.В. Жаров', 'Предзащитная научно-практическая конференция, направленная на демонстрацию и оценку сформированных выпускных ИТ-компетенций: системного мышления, навыков проектирования и разработки программных систем, а также анализа бизнес-процессов. Будущие выпускники ИИЦТ защищали свои выпускные проекты перед экспертной комиссией, демонстрируя готовые программные продукты для реального сектора и внутренних нужд университета. По итогам защиты 1-е место занял Алексей Захаров за инновационное автоматизированное приложение для нормоконтроля выпускных квалификационных работ.'),
(56, 'Студенческая научно-практическая конференция «Командное проектирование в ИТ сфере»', 1, 2, '2025-11-24', '2025-11-26', 'Аудитории СГУВТ', 'ППС кафедры ИС. Председатель экспертной комиссии Д.Н. Голышев', 'Трехдневная научно-практическая конференция, полностью посвященная созданию комплексных коллективных ИТ-решений. Студенты третьего курса ИИЦТ защищали сквозные командные проекты, демонстрируя навыки совместной разработки, распределения ролей в ИТ-команде, а также умение публично презентовать программные продукты. По результатам защиты 1-е место заняли Владимир Беленко, Ярослав Демидов, Кирилл Соболев и Игорь Мясников за инновационный проект «Разработка приложения по созданию макросов», показавший высокую практическую ценность. 2-е место: Анфиса Скляренко, Лилия Менькина и Виктория Емельянова. 3-е место: Андрей Василенко и Глеб Гладков.'),
(57, 'Региональная научно-практическая конференция молодых ученых и студентов «Шаг в науку»', 1, 2, '2025-11-20', '2025-11-20', 'База СибГУТИ', 'Оргкомитет региональной конференции на базе СибГУТИ.', 'Крупная региональная научная площадка, собравшая талантливых молодых исследователей ведущих вузов Сибири. Студенты ИИЦТ СГУВТ представили серию сильных докладов, продемонстрировав глубокие знания и практические результаты в области веб-технологий, телекоммуникаций и искусственного интеллекта. По итогам работы секций представители нашего института завоевали сразу несколько призовых мест: 1-е место (секция «Информационные системы и технологии»): Егор Наумов, Сергей Журавлёв и Данил Ключко с инновационным докладом, посвященным передовым алгоритмам и разработкам в области автоматического перевода с английского языка. 3-е место: Никита Анопченко.'),
(58, 'Отраслевой форум «Крипто-Сибирь»', 1, 2, '2025-11-12', '2025-11-12', 'г. Новосибирск (региональная площадка проведения форума)', 'Оргкомитет форума совместно с ведущими отраслевыми экспертами, разработчиками блокчейн-проектов', 'Посещение масштабного отраслевого форума, посвященного перспективным технологическим трендам в сфере цифровой экономики. В рамках программы студенты ИИЦТ погрузились в проблематику децентрализованных финансов (DeFi), изучили современные протоколы безопасности блокчейн-проектов, а также обсудили реальные кейсы применения NFT-технологий и возможности внедрения цифровых активов в экономический сектор. Участие в форуме позволило будущим ИТ-специалистам расширить профессиональный кругозор, ознакомиться с инновационными решениями «из первых рук» и наладить прямые контакты с экспертами блокчейн-индустрии.'),
(59, 'Дискуссионная площадка, посвященная передовым технологиям, в рамках форума «Дни Сибири и Арктики»', 1, 2, '2025-11-11', '2025-11-11', 'ГПНТБ СО РАН', 'Оргкомитет форума совместно с ведущими учеными СО РАН', 'Участие студентов ИТ-направления во всероссийском научном форуме, ориентированном на стратегическое развитие северных регионов. Будущие ИТ-специалисты ИИЦТ посетили профильную дискуссионную сессию, посвященную интеграции сквозных технологий, систем мониторинга и автоматизации в суровых климатических условиях. В рамках площадки студенты СГУВТ ознакомились с докладами о цифровых двойниках, методах обработки геоданных Арктической зоны и беспилотных технологиях, а также получили возможность напрямую обсудить с практикующими учеными и разработчиками перспективные векторы применения ИТ-решений в реальном секторе экономики макрорегиона.'),
(60, 'Всероссийский ИТ-хакатон «Tender hack»', 2, 2, '2025-10-10', '2025-10-12', 'г. Новосибирск', 'Организаторы ИТ-хакатона «Tender hack» (при поддержке ведущих экспертов в сфере электронных торгов)', 'Крупномасштабное командное соревнование всероссийского уровня, собравшее на одной площадке перспективных молодых ИТ-разработчиков со всей страны. Сборная команда нашего института, объединившая студентов бакалавриата и магистратуры, успешно включилась в интенсивный трехдневный марафон по решению сложнейших практических бизнес-кейсов. Будущие ИТ-специалисты ИИЦТ продемонстрировали высокий уровень подготовки, а также отличные прикладные навыки в области продуктового программирования, интеллектуального анализа больших данных (Data Analysis) и гибкого проектного управления (Project Management), достойно защитив свои программные решения перед федеральной экспертной комиссией.'),
(61, 'Ежегодная студенческая конференция «Современные ИТ-технологии и проектно-технологические решения»', 1, 2, '2025-10-02', '2025-10-04', 'Аудитории СГУВТ', 'Профессорско-преподавательский состав кафедры ИС. Председатель экспертной комиссии С.В. Моторин', 'Трехдневная научно-практическая конференция по итогам защиты производственной практики будущих выпускников. Работа была организована в рамках двух секций, где студенты ИИЦТ презентовали свои прикладные проекты, разработанные для реального производства на основе полученного на предприятиях опыта. По результатам экспертной оценки докладов призовые места распределились следующим образом: 1е-место: Дмитрий Лангер (гр. ИТ-221) за высоко оцененный инновационный доклад «Автоматизация контроля качества на предприятии». 2е-место: Анна Башарина (гр. ИТ-221) и Никита Анопченко (гр. ИТ-221). 3-е место: Степан Глебов, Максим Галкин (гр. ИТ-222), Кирилл Мальцев (гр. ИТ-221) и Владислав Ушаков (гр. ИТ-221).');
INSERT INTO `events` (`id`, `title`, `category_id`, `institute_id`, `date_start`, `date_end`, `location`, `organizer`, `description`) VALUES
(62, 'Парад в честь Дня Великой Победы', 4, 3, '2026-05-09', '2026-05-09', 'Главная площадь Новосибирска (Площадь Ленина)', 'Правительство Новосибирской области и Новосибирский гарнизон.', 'Пятое, юбилейное участие курсантов-речников в главном военном параде города. Этому событию предшествовали месяцы упорных тренировок и оттачивания строевой выучки. Курсанты ИМА продемонстрировали четкий шаг, безупречную выправку и единство строя, пройдя торжественным маршем по главной площади города, чтобы отдать дань памяти и уважения героям Великой Отечественной войны.'),
(63, 'Торжественное открытие навигации на реке Обь.', 9, 3, '2026-04-25', '2026-04-25', 'Михайловская набережная и теплоходы на реке Обь', 'Сибирский государственный университет водного транспорта', 'Традиционный праздник, знаменующий старт сезона речных перевозок. Торжество открылось торжественным маршем курсантов. Прямо на теплоходах представители ИМА СГУВТ организовали для жителей города мастер-классы по вязанию морских узлов, семафорной азбуке и безопасности на воде, а для детей провели интерактивные игры. В это же время на главной сцене набережной проходила праздничная концертная программа с творческими номерами от курсантов.'),
(64, 'Межвузовский этап соревнований по самбо памяти Е.М. Чумакова', 5, 3, '2026-03-18', '2026-03-18', 'Ковры ГАУ НСО «Спортивная школа самбо»', 'Федеральное агентство морского и речного транспорта', 'Масштабный отраслевой чемпионат по самбо среди будущих специалистов флота. На коврах Сибирской Академии самбо спортсмены боролись за право представить свои учебные заведения на всероссийском финале в Москве. На торжественном открытии участников приветствовали руководители спортивных лиг и представители СГУВТ, после чего борцы продемонстрировали высокое мастерство, тактическую гибкость и волю к победе, заложенные традициями профессора Е.М. Чумакова.'),
(65, 'Памятный митинг героям-речникам', 4, 3, '2026-06-22', '2026-06-22', 'Сквер «Водник» памятник героям-речникам', 'Институт «Морская академия» (ИМА) совместно с Новосибирским командным речным училищем им. С.И. Дежнёва', 'Патриотическое мероприятие, посвященное 85-й годовщине начала Великой Отечественной войны. Почетные гости обратились к молодежи с речами о мужестве защитников Родины и важности исторической правды. Участники почтили память погибших минутой молчания, а в финале возложили цветы и зажженные свечи к памятнику героям-речникам.'),
(66, 'XXII Межвузовская олимпиада по математике для нематематических специальностей', 3, 3, '2026-05-13', '2026-05-13', 'База ФГБОУ ВО «НГПУ»', 'Оргкомитет и экспертная комиссия Межвузовской олимпиады на базе НГПУ.', 'Традиционные межвузовские интеллектуальные соревнования, направленные на популяризацию точных наук, развитие логики и нестандартного мышления среди студентов нематематических профилей подготовки. Участники олимпиады решали комплексные прикладные задачи, требующие высокого уровня структурного анализа и гибкого математического подхода. Курсанты Института «Морская академия» вошли в число главных триумфаторов соревнований: Диплом II степени: Данил Савельев. Диплом III степени: Виктор Россоха.'),
(67, 'Экскурсионная программа «Краеведческий музей. История и современность»', 8, 4, '2026-06-05', '2026-06-05', 'Новосибирский государственный краеведческий музей (НГКМ, г. Новосибирск)', 'Экскурсоводы НГКМ совместно с приглашенными командирами и бойцами СВО', 'Комплексное культурно-историческое и патриотическое мероприятие. В рамках первой части программы студенты ИУТП детально изучили постоянную экспозицию музея, познакомившись с бытом, традициями и самобытной культурой коренных народов Сибири, а также ключевыми этапами исторического развития Новосибирской области. Второй, центральной частью выезда стала «живая» встреча с действующими бойцами СВО в формате открытого диалога.'),
(68, 'XXI Международная научная конференция «Логистика-Евразийский мост»', 1, 4, '2026-05-27', '2026-05-30', 'г. Красноярск', 'Оргкомитет международной конференции, ведущие ученые и эксперты', 'Крупное международное научно-отраслевое событие, объединившее ведущих экспертов, практиков и ученых из России, Белоруссии, Казахстана, Китая, Индии, Венгрии и Габона. Конференция была посвящена глобальной трансформации цепей поставок, эффективному управлению материальными потоками и усилению роли внутреннего водного транспорта в современных логистических процессах. Делегация ИУТП СГУВТ продемонстрировала высокие результаты. Студентка Виктория Любимцева (гр. ТЭД-221) завоевала 1-е место в престижном Международном конкурсе научных работ студентов имени Валерии Ермаковой.'),
(69, 'Волонтерская акция «Подарки ветеранам СГУВТ»', 4, 4, '2026-05-01', '2026-05-31', 'г. Новосибирск (выезд по местам проживания ветеранов и пенсионеров вуза)', 'Волонтерский корпус Института управления, транспорта и производительности (ИУТП)', 'Традиционная социально-патриотическая акция адресной помощи и преемственности поколений, приуроченная к празднованию Дня Великой Победы и знаковому 75-летнему юбилею СГУВТ. Активисты и волонтеры ИУТП посетили на дому заслуженных ветеранов и пенсионеров университета, многие годы посвятивших самоотверженному труду на благо развития отечественного водного транспорта. Студенты лично вручили ветеранам праздничные наборы, передали официальные поздравления от лица руководства вуза.'),
(70, 'Международная молодежная школа «Экополис» (включая открытую лекцию)', 1, 4, '2026-05-22', '2026-05-22', 'ФГБОУ ВО «Новосибирский государственный архитектурно-строительный университет»', 'Министерство природных ресурсов и экологии Новосибирской области совместно с НГАСУ.', 'Крупное международное научно-образовательное событие, организованное в рамках реализации национального проекта РФ «Экологическое благополучие». Программа школы была направлена на экологическое просвещение, популяризацию ресурсосберегающих технологий и развитие межвузовской интеграции. Представитель ИУТП СГУВТ Комрон Курбоназаров успешно выступил на международном уровне, презентовав экспертной комиссии свой научно-исследовательский доклад «Исследование снега на территории города Новосибирска», посвященный актуальным региональным проблемам.');
INSERT INTO `event_participants` (`event_id`, `participant_info`, `role_in_event`, `award_details`, `financial_reward`) VALUES
(1, '10 обучающихся (курсанты) и сотрудники СГУВТ', 'Участник / Волонтер', 'Награды отсутствуют', 0.00),
(2, '20 студентов из ИУТП, ИИЦт и ИМА', 'Участник', 'Награды отсутствуют', 0.00),
(3, 'Выпускники, преподаватели и студенты всех институтов', 'Участник', 'Награды отсутствуют', 0.00),
(4, '14 человек из ИМА, ИИЦТ, ИУТП', 'Участник', 'Награды отсутствуют', 0.00),
(5, 'Студенты и курсанты ИИЦТ, ИМА И ИУТП', 'Участник', 'Награды отсутствуют', 0.00),
(6, 'Студенты и курсанты ИИЦТ, ИМА И ИУТП', 'Участник', 'Награды отсутствуют', 0.00),
(7, '10 студентов ИИЦТ и курсантов ИМА', 'Волонтер', 'Награды отсутствуют', 0.00),
(8, 'ИИЦТ', 'Победитель', '1 место (Командное)', 0.00),
(8, 'ИУТП', 'Призер', '2 место (Командное)', 0.00),
(8, 'Анастасия Ломакина (УВТП-241)', 'Победитель', 'Лучший результат (241 очко)', 0.00),
(8, 'Данил Сухотерин (С-231)', 'Победитель', 'Лучший результат (306 очков)', 0.00),
(9, 'Сборная СГУВТ из ИУТП и ИИЦТ', 'Участник', 'Сертификаты и дипломы', 0.00),
